set -eu; sudo -u postgres -- psql -v ON_ERROR_STOP=1 -d branch_stock <<'SQL'
CREATE ROLE stock_app LOGIN NOSUPERUSER NOCREATEDB NOCREATEROLE NOINHERIT NOREPLICATION NOBYPASSRLS;
CREATE ROLE auditor LOGIN NOSUPERUSER NOCREATEDB NOCREATEROLE NOINHERIT NOREPLICATION NOBYPASSRLS;
REVOKE ALL ON DATABASE branch_stock FROM PUBLIC;
REVOKE ALL ON SCHEMA public FROM PUBLIC;
REVOKE ALL ON TABLE stock, supplier_costs FROM PUBLIC;
GRANT CONNECT ON DATABASE branch_stock TO stock_app, auditor;
GRANT USAGE ON SCHEMA public TO stock_app, auditor;
GRANT SELECT ON TABLE stock TO stock_app, auditor;
GRANT UPDATE (quantity) ON TABLE stock TO stock_app;
GRANT SELECT ON TABLE supplier_costs TO auditor;
SQL
sudo -u postgres -- psql -d branch_stock -P pager=off -c "SELECT rolname, rolsuper, rolcreatedb, rolcreaterole, rolcanlogin, rolreplication, rolbypassrls FROM pg_roles WHERE rolname IN ('stock_app','auditor') ORDER BY rolname;" -c "SELECT grantee, table_name, privilege_type FROM information_schema.role_table_grants WHERE grantee IN ('stock_app','auditor') ORDER BY grantee, table_name, privilege_type;" -c "SELECT grantee, table_name, column_name, privilege_type FROM information_schema.role_column_grants WHERE grantee='stock_app' ORDER BY table_name, column_name, privilege_type;"
